package com.mmcafe.board.service;
import com.mmcafe.board.dto.*; import com.mmcafe.board.repository.BoardRepository; import com.mmcafe.common.exception.ResourceNotFoundException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class BoardService { private final BoardRepository repo; public BoardService(BoardRepository repo){this.repo=repo;} @Transactional public BoardResponse createBoard(BoardRequest r){ return repo.save(r.title(),r.content()); } public BoardResponse getBoard(long id){ return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Board not found: "+id)); } public PageResponse<BoardResponse> getBoards(int page,int size){ int p=Math.max(0,page), s=Math.max(1,size); long total=repo.count(); return new PageResponse<>(repo.findAll(p,s),p,s,total,(int)Math.ceil((double)total/s)); } @Transactional public BoardResponse updateBoard(long id,BoardRequest r){ if(!repo.update(id,r.title(),r.content())) throw new ResourceNotFoundException("Board not found: "+id); return getBoard(id);} @Transactional public void deleteBoard(long id){ if(!repo.delete(id)) throw new ResourceNotFoundException("Board not found: "+id);} @Transactional public CommentResponse createComment(long boardId,CommentRequest r){ getBoard(boardId); return repo.saveComment(boardId,r.content()); } public List<CommentResponse> getComments(long boardId){ getBoard(boardId); return repo.findComments(boardId); } @Transactional public void deleteComment(long id){ if(!repo.deleteComment(id)) throw new ResourceNotFoundException("Comment not found: "+id); } }
